164					t.Fatalf("history broken: %+v err=%v", hist, err)
165				}
166			})
167		}
168	
169		// A fresh store instance on the same directory sees the same data.
170		reopened, err := OpenStore(dir)
171		if err != nil {
172			t.Fatal(err)
173		}
174		got, err := reopened.Health(cases[1].id, receive, "v127 ascii", 99)
175		if err != nil || got.Height != 101 {
176			t.Fatalf("long id data not readable after restart: %+v err=%v", got, err)
177		}
178	}
